from __future__ import annotations

PARCEL_RATE = 4.95


def charge(lines: list[tuple[str, int]]) -> float:
    """Return the shipping charge for an order."""
    parcels = sum(quantity for _, quantity in lines)
    return round(PARCEL_RATE * parcels, 2)
